#!/bin/bash
# cc-spike ci.sh, row R5, nonce fcac14136c43. Generated by spike.py. Prints markers; never prints the credential.
N='fcac14136c43'
ROW='R5'
T=$(mktemp -d "${RUNNER_TEMP:-/tmp}/cc-spike.XXXXXX")
pfx() { while IFS= read -r l || [ -n "$l" ]; do printf '%s %s\n' "$1" "$l"; done < "$2"; }
echo "CC-SPIKE START $N"
git push origin "HEAD:refs/heads/ctl-$ROW-$N-co" 2>"$T/keep.err"
echo "CC-SPIKE KEEP-EXIT $?"
pfx 'CC-SPIKE KEEP-ERR' "$T/keep.err"
git fetch --no-tags --depth=1 origin main 2>"$T/fetch.err"
FX=$?
echo "CC-SPIKE FETCH-EXIT $FX"
pfx 'CC-SPIKE FETCH-ERR' "$T/fetch.err"
CX=1
if [ "$FX" = 0 ]; then
  C=$(GIT_AUTHOR_NAME=cc-spike GIT_AUTHOR_EMAIL=cc-spike@example.invalid GIT_COMMITTER_NAME=cc-spike GIT_COMMITTER_EMAIL=cc-spike@example.invalid git commit-tree 'FETCH_HEAD^{tree}' -p FETCH_HEAD -m "cc-spike $N" 2>"$T/commit.err")
  CX=$?
  echo "CC-SPIKE COMMIT-EXIT $CX"
  pfx 'CC-SPIKE COMMIT-ERR' "$T/commit.err"
fi
if [ "$FX" = 0 ] && [ "$CX" = 0 ]; then
  git push origin "$C:refs/heads/ctl-$ROW-$N" 2>"$T/ctl.err"
  echo "CC-SPIKE CTL-EXIT $?"
  pfx 'CC-SPIKE CTL-ERR' "$T/ctl.err"
  git push origin "$C:refs/heads/main" 2>"$T/push.err"
  echo "CC-SPIKE PUSH-EXIT $?"
  pfx 'CC-SPIKE ERR' "$T/push.err"
fi
echo "CC-SPIKE END $N"
rm -rf "$T"
